<script lang="ts">
 import {historyOptions,historyCohort,historySummary,historyBands,historyGroups} from '#lib/evidence-history-analysis.js';
 import {onDestroy,untrack} from 'svelte';import {anyApi} from 'convex/server';import {auth} from '#lib/auth.svelte.ts';import {feed} from '#lib/feed.svelte.ts';import {pct} from '#lib/format.ts';
 let market=$state('all'),direction=$state('all'),line=$state(''),minModel=$state(0),maxModel=$state(100),minFloor=$state(0),minSamples=$state(0),minStrike=$state(0);
 let allowed=$state(false),checked=$state(false),index=$state<any>(null),date=$state(''),rows=$state<any[]>([]),loading=$state(false),error=$state(''),sport=$state('all'),outcome=$state('finished'),search=$state(''),shown=$state(50);let controller:AbortController|undefined;const dayCache=new Map<string,{version:string,rows:any[]}>();
 const today=()=>new Date(Date.now()+3600000).toISOString().slice(0,10),stamp=(n:number)=>new Date(n).toLocaleString('en-NG',{timeZone:'Africa/Lagos',dateStyle:'medium',timeStyle:'short'});
 const dates=$derived(Object.keys(index?.days??{}).sort().reverse());
 $effect(()=>{const client=auth.client;allowed=false;checked=!client;if(!client)return;return client.onUpdate(anyApi.admin.status,{},r=>{allowed=r?.isSuperAdmin===true;checked=true;},()=>{checked=true;error='Administrator access could not be verified.';});});
 $effect(()=>{const generation=feed.data?.generatedAt;if(allowed){generation;untrack(()=>void loadIndex());}else{controller?.abort();index=null;rows=[];dayCache.clear();}});onDestroy(()=>controller?.abort());
 async function json(response:Response){if(!response.ok)throw Error(`History request failed (HTTP ${response.status}).`);let bytes=new Uint8Array(await response.arrayBuffer());if(bytes[0]===31&&bytes[1]===139)bytes=new Uint8Array(await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer());if(bytes.length>64*1024*1024)throw Error('History exceeds the display budget.');return JSON.parse(new TextDecoder().decode(bytes));}
 async function loadIndex(){if(!allowed||loading)return;loading=true;error='';controller=new AbortController();try{const data=await json(await fetch('/api/admin/evidence',{credentials:'same-origin',signal:controller.signal}));if(!allowed)return;index=data.history??null;if(!date||date!=='all'&&!index?.days?.[date])date=Object.keys(index?.days??{}).sort().reverse().find(d=>d<=today())??Object.keys(index?.days??{}).sort()[0]??'';}catch(e){if((e as Error).name!=='AbortError')error=(e as Error).message;}finally{loading=false;}if(date&&allowed)await loadDay();}
 async function loadDay(){if(!allowed||!date||loading)return;controller?.abort();controller=new AbortController();loading=true;error='';rows=[];shown=50;try{const chosen=date==='all'?dates:[date],loaded:any[]=[];for(let i=0;i<chosen.length;i+=4){const batch=await Promise.all(chosen.slice(i,i+4).map(async d=>{const version=String(index?.days?.[d]?.version??'');const cached=dayCache.get(d);if(version&&cached?.version===version)return cached.rows;const data=await json(await fetch(`/api/admin/evidence/history?date=${encodeURIComponent(d)}`,{credentials:'same-origin',signal:controller!.signal}));if(data.schema!==1||data.date!==d||!data.rows)throw Error('Unsupported history record.');const entries=Object.values(data.rows);if(version)dayCache.set(d,{version,rows:entries});return entries;}));if(!allowed)return;loaded.push(...batch.flat());}rows=loaded;}catch(e){if((e as Error).name!=='AbortError')error=(e as Error).message;}finally{loading=false;}}
 const marketChoices=$derived.by(()=>{const map=new Map<string,string>();for(const r of historyOptions(rows)){const key=JSON.stringify([r.scope,r.kind,r.kind==='winner'||r.kind==='other'||r.kind==='handicap'?r.side:'']);map.set(key,`${r.scope.replaceAll('_',' ')} · ${r.kind==='handicap'?(r.side==='home'?'Home':'Away')+' handicap / spread':r.kind==='team-home'?'Home team total':r.kind==='team-away'?'Away team total':r.kind==='match-total'?'Match total':r.title}`);}return [...map.entries()].sort((a,b)=>a[1].localeCompare(b[1]));});
 const valid=$derived([minModel,maxModel,minFloor,minSamples,minStrike].every(Number.isFinite)&&minModel>=0&&maxModel<=100&&maxModel>=minModel&&minFloor>=0&&minFloor<=100&&minSamples>=0&&minStrike>=0&&minStrike<=100&&(line===''||Number.isFinite(Number(line))));
 const cohort=$derived(valid?historyCohort(rows,{sport,market,direction,line,minModel,maxModel,minFloor,minSamples,minStrike,search}):[]);
 const summary=$derived(historySummary(cohort));const bands=$derived(historyBands(cohort));
 const filtered=$derived(cohort.filter(r=>outcome==='all'||(outcome==='finished'?r.state==='finished':r.result===outcome)));
 const categories=$derived(historyGroups(filtered));

 function resetFilters(){market='all';direction='all';line='';minModel=0;maxModel=100;minFloor=0;minSamples=0;minStrike=0;sport='all';search='';outcome='finished';}
 const label=(r:string)=>({won:'Win',lost:'Loss',push:'Stake returned','half-won':'Half win','half-lost':'Half loss',pending:'Awaiting result',ungraded:'Ungraded'}[r]??r);
</script>
<svelte:head><title>Evidence history — PuntersEdge administration</title><meta name="robots" content="noindex,nofollow" /></svelte:head>
<section class="min-w-0 space-y-5">
 <header class="surface p-5 sm:p-7"><p class="text-xs font-semibold uppercase tracking-widest text-model">📜 Recorded pre-match shortlist</p><h1 class="mt-3 text-3xl font-bold">Evidence history</h1><p class="mt-3 max-w-3xl text-sm leading-relaxed text-haze">Selections that met the published default evidence rules before kickoff. Final scores and verified outcomes update after results arrive; the original Model % and recurrence evidence remain frozen.</p><div class="mt-4 flex flex-wrap gap-3"><a class="btn-secondary" href="/admin/evidence">🌡️ Upcoming shortlist</a><button class="btn-secondary" onclick={loadIndex} disabled={!allowed||loading}>Refresh history</button></div></header>
 {#if error}<div class="surface border-loss/50 p-4" role="alert"><p>{error}</p><button class="btn-secondary mt-3" disabled={loading} onclick={loadIndex}>Retry</button></div>{/if}
 {#if !checked}<div class="workspace-state" role="status">Verifying administrator access…</div>{:else if !allowed}<div class="workspace-state"><h2>Administrator access required</h2><a class="btn-primary mt-3" href="/login?next=%2Fadmin%2Fevidence%2Fhistory">Sign in</a></div>{:else}
 <div class="surface p-4"><p class="text-sm text-haze">{#if index?.startedAt}Recording started {stamp(index.startedAt)} WAT.{:else}History will start with the next evidence refresh.{/if} Earlier completed games are not retrospectively labelled as shortlisted. History records default-rule qualification, rather than every administrator's temporary filter settings. Dates use Lagos time.</p></div>
 <div class="surface grid min-w-0 gap-3 p-4 sm:grid-cols-2 xl:grid-cols-4"><label class="grid gap-1 text-xs text-haze">Kickoff date<select class="control" bind:value={date} onchange={loadDay} disabled={loading||!dates.length}><option value="all">All recorded dates</option>{#each dates as d}<option value={d}>{d} · {index.days[d].completed} completed / {index.days[d].count} options</option>{/each}</select></label><label class="grid gap-1 text-xs text-haze">Sport<select class="control" bind:value={sport}><option value="all">All sports</option><option value="football">⚽ Football</option><option value="basketball">🏀 Basketball</option><option value="nba">🏀 NBA</option><option value="hockey">🏒 Hockey</option><option value="baseball">⚾ Baseball</option></select></label><label class="grid gap-1 text-xs text-haze">Outcome<select aria-label="Outcome" class="control" bind:value={outcome}><option value="finished">Completed matches</option><option value="won">Wins</option><option value="lost">Losses</option><option value="push">Stake returned</option><option value="ungraded">Ungraded</option><option value="pending">Awaiting result</option><option value="all">All started selections</option></select></label><label class="grid gap-1 text-xs text-haze">Fixture, league or selection<input class="control" type="search" bind:value={search} placeholder="Search recorded selections" /></label></div>
 <details class="surface p-4"><summary class="min-h-11 cursor-pointer py-3 font-bold">Advanced market &amp; pre-match evidence filters</summary><div class="mt-3 grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><label class="grid gap-1 text-xs">Market family<select class="control" bind:value={market}><option value="all">All markets</option>{#each marketChoices as [key,title]}<option value={key}>{title}</option>{/each}</select></label><label class="grid gap-1 text-xs">Direction<select class="control" bind:value={direction}><option value="all">All directions</option><option value="over">Over</option><option value="under">Under</option><option value="home">Home</option><option value="away">Away</option></select></label><label class="grid gap-1 text-xs">Exact line<input class="control" type="text" inputmode="decimal" bind:value={line} placeholder="e.g. 1.5 or -0.5" /></label><label class="grid gap-1 text-xs">Minimum published Model %<input class="control" type="number" min="0" max="100" bind:value={minModel} /></label><label class="grid gap-1 text-xs">Maximum published Model %<input class="control" type="number" min="0" max="100" bind:value={maxModel} /></label><label class="grid gap-1 text-xs">Minimum saved confidence floor %<input class="control" type="number" min="0" max="100" bind:value={minFloor} /></label><label class="grid gap-1 text-xs">Minimum saved recurrence sample<input class="control" type="number" min="0" bind:value={minSamples} /></label><label class="grid gap-1 text-xs">Minimum saved recurrence strike %<input class="control" type="number" min="0" max="100" bind:value={minStrike} /></label></div><button class="btn-secondary mt-4" onclick={resetFilters}>Reset analysis filters</button>{#if !valid}<p class="mt-3 text-loss" role="alert">Enter valid ranges and percentages.</p>{/if}</details>
 <section class="surface p-4 sm:p-5"><h2 class="text-xl font-bold">Selected cohort performance</h2><p class="mt-2 text-sm text-haze">Uses all outcomes matching your market and pre-match evidence filters. The outcome display filter does not change these statistics. Choose All recorded dates for the complete retained sample.</p><div class="mt-4 grid grid-cols-2 gap-3 lg:grid-cols-4">{#each [['Binary results',summary.binary],['Wins',summary.wins],['Losses',summary.losses],['Observed strike',summary.strike===null?'Unavailable':pct(summary.strike,1)],['Distinct fixtures',summary.fixtures],['Pending',summary.pending],['Other / ungraded',summary.other],['Mean published Model',summary.meanModel===null?'Unavailable':pct(summary.meanModel,1)]] as [title,n]}<div class="rounded-xl border border-line p-3"><p class="text-xs text-haze">{title}</p><p class="mt-2 text-xl font-bold">{n}</p></div>{/each}</div><p class="mt-4 text-sm">{summary.wins} wins and {summary.losses} losses out of {summary.binary} binary results.{#if summary.binary}{' '}Observed 95% win-rate interval: {pct(summary.interval.low,1)}–{pct(summary.interval.high,1)}.{/if}{#if summary.lossModelRange}{' '}Losses occurred at published Model {pct(summary.lossModelRange[0],1)}–{pct(summary.lossModelRange[1],1)}.{/if}</p><p class="mt-3 text-xs text-haze">{summary.binary<30?'Small sample: insufficient to describe a stable pattern.':'Observed historical performance; consistency is not established by win count alone.'} Multiple options from one fixture are related. Returned, partial and ungraded outcomes are excluded from the binary rate. This is exploratory analysis of recorded shortlist picks, not independent validation or guaranteed future wins or profitable prices.</p><details class="mt-4"><summary class="min-h-11 cursor-pointer py-3 font-semibold">Win/loss breakdown by published Model %</summary><div class="max-w-full overflow-x-auto"><table><thead><tr><th>Model band</th><th>Options</th><th>Wins</th><th>Losses</th><th>Strike</th><th>95% interval</th></tr></thead><tbody>{#each bands as band}<tr><td>{band.label}</td><td>{band.options}</td><td>{band.wins}</td><td>{band.losses}</td><td>{band.strike===null?'Unavailable':pct(band.strike,1)}</td><td>{band.binary?`${pct(band.interval.low,1)}–${pct(band.interval.high,1)}`:'Unavailable'}</td></tr>{/each}</tbody></table></div></details></section>
 {#if loading}<div class="workspace-state" role="status">Loading recorded history…</div>{:else if !filtered.length}<div class="workspace-state"><h2>No recorded selections match these filters</h2><p>Upcoming entries move into this view after kickoff. Completed results will appear after the scheduled pipeline updates. Missing or unsupported outcomes stay ungraded.</p></div>{:else}
 <div class="space-y-6">{#each categories as category}<section class="space-y-3"><h2 class="text-2xl font-bold capitalize">{category.sport}</h2>{#each category.markets as group}<details class="surface history-market overflow-hidden" data-sport={category.sport}><summary class="min-h-14 cursor-pointer p-4 font-bold">{group.title} · {group.count} displayed options</summary><div class="space-y-4 p-3">{#each group.fixtures.slice(0,shown) as fixture}<article class="overflow-hidden rounded-xl border border-line"><h3 class="p-4 font-bold fixture-name">{fixture.matchTitle}</h3><div class="max-w-full overflow-x-auto"><table><thead><tr><th>#</th><th>Fixture & competition</th><th>Recorded selection</th><th>Pre-match Model %</th><th>Evidence at qualification</th><th>Final score & outcome</th></tr></thead><tbody>{#each fixture.options as r,i}<tr data-sport={r.sport}><td>{i+1}</td><td><a class="fixture-name font-semibold hover:underline" href="/match?id={encodeURIComponent(r.fixtureId)}">{r.matchTitle}</a><p class="mt-2 text-xs text-haze">{r.league}{r.tournament&&r.tournament!==r.league?' · '+r.tournament:''}{r.country?' · '+r.country:''}</p><p class="mt-2 text-xs text-haze">{r.sport} · {stamp(r.kickoff)} WAT</p></td><td><strong>{r.selection}</strong><p class="mt-2 text-xs text-haze">{r.group}</p><p class="mt-2 text-xs text-haze">Published {stamp(r.publishedAt)}</p></td><td class="font-bold text-model">{pct(r.modelProb,1)}</td><td><strong>{pct(r.cohort.strikeRate,1)} strike</strong><p class="mt-2 text-xs text-haze">{r.cohort.won} wins / {r.cohort.binaryN} binary results</p><p class="mt-2 text-xs text-haze">{pct(r.cohort.interval.low,1)} historical floor</p><meter class="mt-2 w-full" min="0" max="1" low="0.5" high="0.7" optimum="1" value={r.cohort.interval.low} aria-label="Saved historical confidence floor">{pct(r.cohort.interval.low,1)}</meter></td><td><strong class="fixture-name">{r.score?`${r.score.home}–${r.score.away}`:'Score unavailable'}</strong>{#if r.score?.regHome!==undefined&&(r.score.regHome!==r.score.home||r.score.regAway!==r.score.away)}<p class="text-xs text-haze">Regulation {r.score.regHome}–{r.score.regAway}</p>{/if}<p class="mt-2 font-bold" class:text-model={r.result==='won'} class:text-loss={r.result==='lost'} class:text-book={!['won','lost'].includes(r.result)}>{label(r.result)}</p><p class="mt-1 text-xs text-haze">{r.state}</p></td></tr>{/each}</tbody></table></div></article>{/each}{#if group.fixtures.length>shown}<button class="btn-secondary" onclick={()=>shown+=50}>Show 50 more fixtures</button>{/if}</div></details>{/each}</section>{/each}</div>{/if}
 {/if}
</section>
<style>
 .history-market[data-sport="football"]>summary{background:#d9f8e5;color:#123d29}.history-market[data-sport="hockey"]>summary{background:#dcf3ff;color:#163b52}.history-market[data-sport="basketball"]>summary,.history-market[data-sport="nba"]>summary{background:#fff0c2;color:#503811}
 .control{min-width:0;width:100%;min-height:44px;border:1px solid var(--color-line);border-radius:.75rem;padding:.65rem;background:var(--color-ink);color:var(--color-chalk);font-size:.875rem;}table{min-width:1050px;width:100%;font-size:.875rem;}th,td{text-align:left;vertical-align:top;padding:1rem;border-bottom:1px solid var(--color-line);}th{font-size:.7rem;text-transform:uppercase;color:var(--color-haze);}td:nth-child(2){min-width:230px;}td:nth-child(3){min-width:230px;}tr[data-sport="football"] td:first-child{border-left:4px solid #86efac;}tr[data-sport="hockey"] td:first-child{border-left:4px solid #7dd3fc;}tr[data-sport="basketball"] td:first-child,tr[data-sport="nba"] td:first-child{border-left:4px solid #fcd34d;}tbody tr:hover{background:color-mix(in srgb,var(--color-model) 5%,transparent);}
</style>
